// ASP.NET Core middleware IS the GoF patterns, wired by the framework.
var app = builder.Build();

app.UseMiddleware<ExceptionHandlingMiddleware>(); // try/catch around the rest
app.UseMiddleware<RequestLoggingMiddleware>();    // decorator: adds logging
app.UseAuthentication();                          // decorates HttpContext.User
app.UseAuthorization();                           // gate (chain link)
app.MapControllers();                             // terminal handler

// Each middleware: handle OR forward — textbook Chain of Responsibility.
public sealed class RequestLoggingMiddleware(RequestDelegate next, ILogger<RequestLoggingMiddleware> log) {
    public async Task InvokeAsync(HttpContext ctx) {
        var sw = Stopwatch.StartNew();
        await next(ctx);                            // forward down the chain
        log.LogInformation("{Method} {Path} -> {Status} in {Ms}ms",
            ctx.Request.Method, ctx.Request.Path, ctx.Response.StatusCode, sw.ElapsedMilliseconds);
    }
}
